import{Utils}from"../utils.min.js?v=1.0.0";import Base_Component from"../component/base-component.min.js?v=1.0.0";let Cart_Based_Shipping={extends:Base_Component,template:"#shipflex-cart-based-shipping-feature-component",props:{featureData:{default:null,type:[null,Object]}},data(){return{calculation_value:"",calculate_basis:"fixed_amount",shipping_cost_ranges:[],calculation_type:"per_unit_or_percentage",...shipflex_admin?.features?.["cart-based-shipping"],...this.featureData}},computed:{component_data(){return JSON.parse(JSON.stringify(this.$data))},show_calculation_value(){return"fixed_amount"==this.calculate_basis||"fixed_amount"!=this.calculate_basis&&"shipping_cost_ranges"!=this.calculation_type},calculation_metrics(){return shipflex_admin.calculation_metrics},calculation_type_label(){return this.get_calculation_type_label(this.calculate_basis)}},methods:{add_shipping_cost_range(){Array.isArray(this.shipping_cost_ranges)||(this.shipping_cost_ranges=[]),this.shipping_cost_ranges.push({id:Utils.generate_uuid()})},duplicate_shipping_cost_range(t,e){this.shipping_cost_ranges.splice(e,0,t)},delete_shipping_cost_range(t){this.shipping_cost_ranges.splice(t,1)}}};export default Cart_Based_Shipping;